float musicalAccent(float value) {
 float activity=vrchReadSignal(0)+vrchReadSignal(1)+vrchReadSignal(2);
 float crisp=smoothstep(.02,.18,vrchReadSignal(2));
 return smoothstep(.005,.25,value)*mix(1.0,.12+.88*crisp,step(.001,activity));
}

float portalDistance(vec2 p,float size) {
 vec2 q=abs(p)-vec2(size*1.45,size);return max(q.x,q.y);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 p=(2.0*fragCoord-iResolution.xy)/iResolution.y;
 float phase=vrchPhase_speed(), hit=musicalAccent(uParam_accent);
 p.x+=.075*sin(phase*.23);p.y+=.035*cos(phase*.18);
 vec3 color=vec3(.004,.006,.012);
 float angle=uParam_twist*.3;
 for(int i=0;i<16;i++) {
  float z=mod(float(i)/16.0+phase*.045,1.0);
  float size=.055+2.15*pow(z,1.75);
  float a=angle*(1.0-z)+.02*sin(phase*.21+z*4.0);
  vec2 q=mat2(cos(a),-sin(a),sin(a),cos(a))*p;
  float d=portalDistance(q,size), width=(.008+size*.021)*uParam_width;
  float fade=smoothstep(.0,.12,z)*(1.0-smoothstep(.88,1.0,z));
  float face=(1.0-smoothstep(width,width+.002,abs(d)))*fade;
  float edge=exp(-pow(abs((d+width*.6)/max(.002,width*.14)),2.0))*fade;
  float light=.38+.62*pow(.5+.5*sin(z*7.0-phase*.55+q.x*.7),3.0);
  float side=smoothstep(-size*.65,size*.65,q.x+q.y*.5);
  vec3 hue=mix(vec3(.68,.20,.065),vec3(.065,.40,.59),side);
  hue=mix(hue,uParam_tint.rgb,.16);
  color+=hue*face*(.11+z*.2)*light;
  color+=mix(hue,vec3(.80,.84,.82),.32)*edge*(.3+uParam_light*.9+hit*.6)*pow(z,.35);
  float glow=exp(-abs(d)/max(.006,width*2.4))*fade;
  color+=hue*glow*.085*uParam_light*light;
 }
 // A restrained floor reflection gives the portals weight without an extra surface layer.
 float floorLight=exp(-pow(abs((p.y+.71)/.16),2.0))*exp(-pow(abs(p.x/1.25),4.0));
 color+=vec3(.012,.019,.035)*floorLight;
 fragColor=vec4(1.0-exp(-color*1.28),1.0);
}
